<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useQRCode} from '@vueuse/integrations/useQRCode'
import {api,session} from '../api'
import Icon from '../components/Icon.vue'
const route=useRoute(),router=useRouter(),step=ref('login'),busy=ref(false),error=ref(''),success=ref(''),email=ref(''),password=ref(''),confirmation=ref(''),oldPassword=ref(''),otp=ref(''),show=ref(false),uri=ref(''),secret=ref(''),person=ref('')
const qr=useQRCode(uri,{width:220,margin:2,color:{dark:'#243658',light:'#ffffff'}})
const titles={login:'Sistema de Gestión de Notas ULS',setup:'¡Bienvenido a ULS!',otp:'Verifica tu identidad',change:'Crea tu nueva contraseña',forgot:'Recupera tu acceso',reset:'Restablece tu contraseña',activated:'¡Tu cuenta está lista!'}
const descriptions={login:'Ingresa tu correo electrónico y contraseña para acceder a tu cuenta.',setup:'Nos alegra que formes parte de nuestra comunidad. Tu nueva etapa comienza aquí.',otp:'Ingresa el código generado en tu app para el inicio de sesión.',change:'Por seguridad, cambia tu contraseña temporal antes de continuar.',forgot:'Te enviaremos un enlace para restablecer tu contraseña.',reset:'Elige una contraseña segura para volver a ingresar.',activated:'Google Authenticator se configuró correctamente. Ya puedes iniciar sesión.'}
const title=computed(()=>titles[step.value])
async function init(){error.value='';success.value='';otp.value='';if(route.path.startsWith('/activar/')){step.value='setup';try{const d=await api('/auth/invitations/'+route.params.token);uri.value=d.uri;secret.value=d.secret;person.value=d.name}catch(e){error.value=e.message}}else if(route.path==='/cambiar-clave')step.value='change';else if(route.path==='/recuperar')step.value='forgot';else if(route.path.startsWith('/restablecer/')){step.value='reset';email.value=route.query.email||''}else step.value='login'}
watch(()=>route.fullPath,init);onMounted(init)
async function submit(){busy.value=true;error.value='';success.value='';try{
 if(step.value==='login'){const d=await api('/auth/login',{method:'POST',body:{email:email.value,password:password.value}});password.value='';if(d.user){session.user=d.user;await router.replace('/')}else step.value='otp'}
 else if(step.value==='setup'){const d=await api('/auth/invitations/'+route.params.token+'/confirm',{method:'POST',body:{code:otp.value}});uri.value='';secret.value='';otp.value='';session.user=d.user;await router.replace('/')}
 else if(step.value==='otp'){const d=await api('/auth/verify',{method:'POST',body:{code:otp.value}});session.user=d.user;router.replace('/')}
 else if(step.value==='change'){const d=await api('/auth/password',{method:'PUT',body:{current_password:oldPassword.value,password:password.value,password_confirmation:confirmation.value}});session.user=d.user;router.push('/')}
 else if(step.value==='forgot'){await api('/auth/forgot-password',{method:'POST',body:{email:email.value}});success.value='Si el correo está registrado, recibirás un enlace de recuperación.'}
 else if(step.value==='reset'){await api('/auth/reset-password',{method:'POST',body:{email:email.value,token:route.params.token,password:password.value,password_confirmation:confirmation.value}});await router.push('/login');success.value='Contraseña actualizada. Inicia sesión con tu nuevo acceso.'}
 }catch(e){error.value=Object.values(e.errors||{}).flat().join(' ')||e.message}finally{busy.value=false}}
</script>
<template><div class="auth-layout" :class="'auth-step-'+step">
 <section class="auth-main"><div class="auth-top-note"><Icon name="ShieldCheck" :size="16"/> Conexión segura · Tu portal académico</div><div class="auth-form-wrap"><div class="auth-mobile-brand"><svg class="access-mark" viewBox="0 0 120 120" fill="none" aria-hidden="true"><path d="M55 20H39Q22 20 22 37V53M42 7L57 22 42 37" stroke="#3923AA"/><path d="M99 55V39Q99 22 82 22H67M112 42L97 57 82 42" stroke="#7778C8"/><path d="M65 100H81Q98 100 98 83V67M78 113L63 98 78 83" stroke="#A3A7E8"/><path d="M21 65V81Q21 98 38 98H53M8 78L23 63 38 78" stroke="#C9CEF5"/></svg></div><div class="auth-symbol"><Icon :name="step==='setup'?'QrCode':step==='otp'?'ShieldCheck':step==='activated'?'CircleCheck':'LockKeyhole'" :size="27"/></div><span class="eyebrow">CONSULTA DE NOTAS ULS</span><h2>{{step==='setup'&&person?'¡Bienvenido, '+person.split(' ')[0]+'!':title}}</h2><p class="auth-description">{{descriptions[step]}}</p>
 <v-alert v-if="error" type="error" variant="tonal" class="mb-5" role="alert">{{error}}</v-alert><v-alert v-if="success" type="success" variant="tonal" class="mb-5">{{success}}</v-alert>
 <form @submit.prevent="submit" v-if="step!=='activated'">
 <template v-if="['login','forgot','reset'].includes(step)"><label class="field-label" for="email">Correo electrónico</label><v-text-field class="auth-email-field" id="email" v-model="email" type="email" placeholder="Correo electr?nico" aria-label="Correo electr?nico" autocomplete="username" required :maxlength="255"><template #prepend-inner><Icon name="Mail" :size="18"/></template></v-text-field></template>
 <template v-if="step==='change'"><label class="field-label">Contraseña temporal</label><v-text-field v-model="oldPassword" type="password" autocomplete="current-password" required /></template>
 <template v-if="['login','change','reset'].includes(step)"><div class="label-row"><label class="field-label" for="password">{{step==='login'?'Contraseña':'Nueva contraseña'}}</label><router-link v-if="step==='login'" to="/recuperar">¿Olvidaste tu contraseña?</router-link></div><v-text-field class="auth-password-field" id="password" v-model="password" :type="show?'text':'password'" :placeholder="step==='login'?'Ingresa tu contraseña':'Mínimo 12 caracteres'" :autocomplete="step==='login'?'current-password':'new-password'" required :minlength="step==='login'?1:12"><template #prepend-inner><Icon name="LockKeyhole" :size="18"/></template><template #append-inner><button type="button" @click="show=!show" :aria-label="show?'Ocultar contraseña':'Mostrar contraseña'"><Icon :name="show?'EyeOff':'Eye'" :size="18"/></button></template></v-text-field></template>
 <template v-if="['change','reset'].includes(step)"><label class="field-label auth-confirm-label">Confirmar nueva contraseña</label><v-text-field class="auth-confirm-field" v-model="confirmation" type="password" autocomplete="new-password" minlength="12" required/><p class="password-hint">Usa al menos 12 caracteres, mayúsculas, minúsculas, números y símbolos.</p></template>
 <template v-if="step==='setup'"><div v-if="qr" class="qr-block"><img :src="qr" alt="Código QR para vincular Google Authenticator" width="200" height="200"/></div><p class="otp-instruction">Escanea el QR en tu APP. Una vez configurado ingresa el codigo generado para iniciar sesion</p><details v-if="secret" class="manual-key"><summary>¿No puedes escanear el código?</summary><p>En Google Authenticator selecciona “Ingresar clave de configuración”, tipo basado en tiempo.</p><code>{{secret}}</code></details></template>
 <template v-if="['setup','otp'].includes(step)"><label class="field-label otp-label">Código de verificación</label><v-otp-input v-model="otp" :length="6" type="number" autocomplete="one-time-code" variant="outlined" color="primary" :disabled="busy"/><p class="otp-caption">El código de 6 dígitos cambia cada 30 segundos.</p></template>
 <v-btn block color="primary" size="x-large" type="submit" :loading="busy" :disabled="['setup','otp'].includes(step)&&otp.length!==6" class="auth-submit">{{step==='login'?'Iniciar sesión':step==='forgot'?'Enviar enlace':step==='change'?'Guardar y continuar':step==='reset'?'Guardar contraseña':'Verificar y continuar'}}<Icon name="ArrowRight" :size="19" class="ml-3"/></v-btn>
 </form>
 <v-btn v-else block color="primary" size="x-large" to="/login">Ir al inicio de sesión <Icon name="ArrowRight" class="ml-3"/></v-btn>
 <div v-if="step==='login'" class="login-recovery"><router-link to="/recuperar">Recupera tu contrase?a</router-link></div>
 <div v-if="['forgot','reset','otp'].includes(step)" class="back-login"><router-link to="/login" @click="step='login'">Volver al inicio de sesión</router-link></div>
 <div class="auth-help"><Icon name="CircleHelp" :size="17"/><p v-if="step==='forgot'||step==='otp'">¿Olvidaste tu clave o perdiste tu autenticador?<br><span>Solicita al administrador restablecer tu acceso y generar un QR nuevo.</span></p><p v-else>¿Necesitas ayuda con tu acceso?<br><span>Contacta al administrador de tu institución.</span></p></div>
 </div><footer class="auth-footer">© 2026 Universidad Luterana Salvadoreña <span>Todos los derechos reservados.</span></footer></section></div></template>
